(* [comment removed for export] *)
Definition art_cost (ev : aev) : Z :=
  match ev with
  | AMmapFixed _ len => len
  | AMmapNull len _ => len + len / 8 + 8192
  | _ => 0
  end.
Definition art_cost_sum (log : list aev) : Z := fold_right (fun ev z => art_cost ev + z) 0 log.

