Lemma view_unfill : forall (H H' : word -> bool) M (r len : Z),
  0 <= r < 2 ^ 64 -> 0 <= len < 2 ^ 64 ->
  (forall a : word, ~ (r <= bv_unsigned a < r + len) -> H' a = H a) ->
  mrestrict H' (unfill (Z_to_bv 64 r) (Z_to_bv 64 len) M) = art_unmap (mrestrict H M) r len.
Proof.
