  (forall a : word, lo <= bv_unsigned a < hi -> H' a = false /\ M a <> None /\ (H a = true -> M a = Some (Z_to_bv 8 0))) ->
  (forall a : word, ~ (lo <= bv_unsigned a < hi) -> H' a = H a) ->
  mrestrict H' M = art_reveal (mrestrict H M) lo hi.
Proof.
