Lemma maps_subtract_pos : forall l lo hi,
  (forall q, In q l -> 0 < bv_unsigned (snd q)) -> BA.ivs_wf l -> lo <= hi ->
  forall q, In q (maps_subtract l lo hi) -> 0 < bv_unsigned (snd q).
