Lemma overlap_sum_one : forall l R lo hi,
  List.NoDup l -> lo <= hi ->
  (forall q, In q l -> q <> R -> BA.B q + BA.S q <= lo \/ hi <= BA.B q) ->
  BA.overlap_sum l lo hi <= hi - lo.
Proof.
