Lemma live_word : forall L p, live_ok L -> In p L ->
  BA.B (toW p) = fst p /\ BA.S (toW p) = snd p /\ 0 < fst p /\ 0 < snd p /\ fst p + snd p < 2 ^ 64.
Proof.
