Lemma iov_prefix_accesses_nolazy : forall L iovs left,
  Forall (fun bn => nolazy_rng L (fst bn) (bv_unsigned (snd bn))) iovs ->
  acc_nolazy L (iov_prefix_accesses iovs left).
Proof.
